do $$ declare r record; begin for r in select p.oid,n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('get_single_use_access_offers','purchase_single_use_access','redeem_single_use_access') loop execute format('revoke execute on function %I.%I(%s) from anon',r.nspname,r.proname,r.args); execute format('grant execute on function %I.%I(%s) to authenticated',r.nspname,r.proname,r.args); end loop; end $$;
